    public static IReadOnlyList<ArtworkSearchRequest> GetDailySelection(int target, DateOnly? date = null)
    {
        var count = Math.Clamp((target + 2) / 3, 1, Profiles.Length);
        var day = (date ?? DateOnly.FromDateTime(DateTime.UtcNow)).DayNumber;
        var offset = Math.Abs(day % Profiles.Length);
        return Enumerable.Range(0, count).Select(index => Profiles[(offset + index) % Profiles.Length]).ToArray();
